CREATE TABLE `adjustments` (
  `adjustment_id` varchar(190) NOT NULL,
  `adjustment_code` varchar(80) NOT NULL,
  `adjustment_date` date NOT NULL,
  `material_id` varchar(120) NOT NULL,
  `adjustment_type` varchar(20) NOT NULL,
  `qty` decimal(18,4) NOT NULL,
  `unit_cost` decimal(22,8) NOT NULL,
  `amount` decimal(22,6) NOT NULL,
  `reason_code` varchar(80) NOT NULL,
  `reason_detail` varchar(1000) NOT NULL,
  `reference_transaction_id` varchar(190) DEFAULT NULL,
  `requested_by` varchar(190) NOT NULL,
  `approved_by` varchar(190) DEFAULT NULL,
  `status` varchar(40) NOT NULL DEFAULT 'POSTED',
  `posted_by` varchar(190) DEFAULT NULL,
  `posted_at` datetime DEFAULT NULL,
  `note` text DEFAULT NULL,
  `client_request_id` varchar(190) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`adjustment_id`),
  UNIQUE KEY `adjustment_code` (`adjustment_code`),
  UNIQUE KEY `client_request_id` (`client_request_id`)
