--
-- Table structure for table `purchase_request_lines`
--

DROP TABLE IF EXISTS `purchase_request_lines`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `purchase_request_lines` (
  `pr_ref_key` varchar(190) NOT NULL,
  `pr_code` varchar(120) NOT NULL,
  `pr_date` date DEFAULT NULL,
  `supplier_id` varchar(120) NOT NULL,
  `supplier_name` varchar(255) DEFAULT NULL,
  `order_code` varchar(120) DEFAULT NULL,
  `execution_code` varchar(120) DEFAULT NULL,
  `product_code` varchar(160) DEFAULT NULL,
  `material_id` varchar(120) NOT NULL,
  `material_name` varchar(255) DEFAULT NULL,
  `uom` varchar(40) DEFAULT NULL,
  `gross_requirement_qty` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `reserved_stock_qty` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `net_requirement_qty` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `ordered_qty` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `estimated_unit_price` decimal(20,6) NOT NULL DEFAULT 0.000000,
  `estimated_amount` decimal(20,4) NOT NULL DEFAULT 0.0000,
  `received_qty` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `remaining_qty` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `required_date` date DEFAULT NULL,
  `line_status` varchar(60) DEFAULT NULL,
  `operational_active_flag` tinyint(1) NOT NULL DEFAULT 1,
  `source_row_key` varchar(190) DEFAULT NULL,
  `synced_at` datetime DEFAULT NULL,
  PRIMARY KEY (`pr_ref_key`),
  KEY `idx_pr_open_supplier` (`supplier_id`,`remaining_qty`,`pr_date`),
  KEY `idx_pr_code` (`pr_code`,`remaining_qty`),
  KEY `idx_pr_execution` (`execution_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

