DROP TABLE IF EXISTS `stock_ledger`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `stock_ledger` (
  `ledger_id` varchar(190) NOT NULL,
  `posted_at` datetime NOT NULL,
  `transaction_date` date NOT NULL,
  `transaction_type` varchar(60) NOT NULL,
  `transaction_id` varchar(190) NOT NULL,
  `transaction_line_id` varchar(190) NOT NULL,
  `document_code` varchar(80) NOT NULL,
  `material_id` varchar(120) NOT NULL,
  `qty_in` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `qty_out` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `unit_cost` decimal(22,8) NOT NULL DEFAULT 0.00000000,
  `amount_in` decimal(22,6) NOT NULL DEFAULT 0.000000,
  `amount_out` decimal(22,6) NOT NULL DEFAULT 0.000000,
  `running_qty` decimal(18,4) NOT NULL DEFAULT 0.0000,
  `running_value` decimal(22,6) NOT NULL DEFAULT 0.000000,
  `avg_cost_after` decimal(22,8) NOT NULL DEFAULT 0.00000000,
  `order_code` varchar(120) DEFAULT NULL,
  `execution_code` varchar(120) DEFAULT NULL,
  `product_code` varchar(160) DEFAULT NULL,
  `supplier_id` varchar(120) DEFAULT NULL,
  `pr_code` varchar(120) DEFAULT NULL,
  `created_by` varchar(190) NOT NULL,
  `source_environment` varchar(40) NOT NULL DEFAULT 'PRODUCTION',
  `source_client_request_id` varchar(190) NOT NULL,
  PRIMARY KEY (`ledger_id`),
  UNIQUE KEY `uq_ledger_transaction` (`transaction_type`,`transaction_line_id`),
  KEY `idx_ledger_material_time` (`material_id`,`posted_at`),
  KEY `idx_ledger_execution` (`execution_code`,`posted_at`),
  KEY `idx_ledger_document` (`document_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
