CREATE TABLE `suppliers` (
  `supplier_id` varchar(120) NOT NULL,
  `supplier_short_code` varchar(190) DEFAULT NULL,
  `supplier_display_name` varchar(255) NOT NULL,
  `legal_name` varchar(255) DEFAULT NULL,
  `tax_code` varchar(80) DEFAULT NULL,
  `misa_supplier_code` varchar(120) DEFAULT NULL,
  `misa_supplier_name` varchar(255) DEFAULT NULL,
  `contact_person` varchar(190) DEFAULT NULL,
  `phone` varchar(80) DEFAULT NULL,
  `bank_account` varchar(120) DEFAULT NULL,
  `bank_name` varchar(190) DEFAULT NULL,
  `account_holder` varchar(190) DEFAULT NULL,
  `supplier_group` varchar(120) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `synced_at` datetime DEFAULT NULL,
  PRIMARY KEY (`supplier_id`),
  KEY `idx_supplier_name` (`supplier_display_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
